import 'package:flutter_test/flutter_test.dart';
import 'package:mobile_iii_3d/services/slicer_parser_service.dart';

void main() {
  test('SlicerParserService parses GCODE comments properly', () {
    const gcodeSample = '''
; GCODE Sample generated by OrcaSlicer
; estimated printing time (normal mode) = 2h 15m
; filament used [g] = 45.5, 12.0
; TIME:8100
G28
T0
G1 X10 Y10 E5
T1
G1 X20 Y20 E5
T0
G1 X30 Y30 E5
M84
''';

    final result = SlicerParserService.parseGcodeString(gcodeSample, 'modelo_teste.gcode');

    expect(result.fileName, 'modelo_teste.gcode');
    // TIME:8100 -> 8100/60 = 135 minutos = 2h 15m
    expect(result.totalTimeMinutes, 135);
    // Filamentos usados: 45.5 + 12.0 = 57.5g
    expect(result.totalWeightGrams, closeTo(57.5, 0.1));
    expect(result.filaments.length, 2);
    // Trocas de ferramenta T0, T1, T0 -> 3 ferramentas = 2 trocas
    expect(result.filamentChanges, 2);
  });
}
